1	// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
2	// Authoring builds as CODE: design one bay, tile it; mirror for symmetry; protect function with a guard.
3	// Coordinate bookkeeping is where design time and errors go — write a short generator script with these helpers
4	// instead of typing hundreds of coordinates.
5	//
6	//   import { load, Grid, guard, tile, mirrorX, B, face } from "<plugin>/tools/src/build.mjs"
7	//   const g = guard(load("in.nbt"))                 // refuses writes into functional cells (see check.mjs)
8	//   runParts(g, [["shell", shellPart], ["porch", porchPart]], { palette: "palette.json" })  // later parts only add
9	//   tile(g, { from: 1, step: 4, count: 5, axis: "z" }, (z) => bay(g, z))
10	//   g.save("out.nbt")
11	import { existsSync, readFileSync, writeFileSync } from "node:fs";
12	import { load, Grid, ns } from "./structure.mjs";
13	import { t } from "./nbt.mjs";
14	import { functionalCells } from "./check.mjs";
15	export { load, Grid };
16	
17	// ---- directions -------------------------------------------------------------------------------------------------
18	export const DIRS = { north: [0, 0, -1], south: [0, 0, 1], west: [-1, 0, 0], east: [1, 0, 0] };
19	export const OPPOSITE = { north: "south", south: "north", east: "west", west: "east", up: "down", down: "up" };
20	const CW = { north: "east", east: "south", south: "west", west: "north" };
21	export const face = {
22	  opposite: (f) => OPPOSITE[f],
23	  cw: (f) => CW[f],
24	  ccw: (f) => OPPOSITE[CW[f]],
25	  /** Mirror a facing across the YZ plane (x -> -x) or XY plane (z -> -z). */
26	  mirrorX: (f) => (f === "east" ? "west" : f === "west" ? "east" : f),
27	  mirrorZ: (f) => (f === "north" ? "south" : f === "south" ? "north" : f),
28	};
29	
30	// ---- block helpers: return [block, state] pairs for g.set(x, y, z, ...B.stairs(...)) ----------------------------
31	// Stairs `facing` = the side of the full-height back; a cornice/bracket lip toward the street uses
32	// facing = the INWARD direction with half: "top".
33	export const B = {
34	  stairs: (mat, facing, half = "bottom", shape = "straight") => [`${mat}_stairs`, { facing, half, shape, waterlogged: "false" }],
35	  slab: (mat, type = "bottom") => [`${mat}_slab`, { type, waterlogged: "false" }],
36	  log: (mat, axis = "y") => [`${mat}_log`, { axis }],
37	  wood: (mat, axis = "y") => [`${mat}_wood`, { axis }],
38	  pillar: (block, axis = "y") => [block, { axis }],
39	  trapdoor: (mat, facing, half = "bottom", open = false) => [`${mat}_trapdoor`, { facing, half, open: String(open), powered: "false", waterlogged: "false" }],
40	  door: (mat, facing, half = "lower", hinge = "left") => [`${mat}_door`, { facing, half, hinge, open: "false", powered: "false" }],
41	  fence: (mat) => [`${mat}_fence`, {}],
42	  wall: (mat) => [`${mat}_wall`, {}],
43	  pane: (block = "glass_pane") => [block, {}],
44	  lantern: (hanging = false) => ["lantern", { hanging: String(hanging), waterlogged: "false" }],
45	  chain: (axis = "y", version26 = true) => [version26 ? "iron_chain" : "chain", { axis, waterlogged: "false" }],
46	  wallTorch: (facing) => ["wall_torch", { facing }],
47	  block: (name) => [name, {}],
48	  /**
49	   * A banner with patterns: [block, state, nbt] for g.set(x, y, z, ...B.banner(...)). patterns: [[pattern, colour], ...]
50	   * (ids such as stripe_center, border, cross, rhombus, flower, globe, gradient, half_horizontal, curly_border).
51	   * wall: hung on the block behind it, facing `facing`; standing: `rotation` 0..15 (0 faces south). legacy: the
52	   * pre-1.20.5 Patterns/Pattern/Color form (for 1.20.4 and older).
53	   */
54	  banner: (color, patterns = [], { wall = true, facing = "north", rotation = 0, legacy = false } = {}) => {
55	    const block = wall ? `${color}_wall_banner` : `${color}_banner`, state = wall ? { facing } : { rotation: String(rotation) };
56	    const pats = patterns.map((p) => (Array.isArray(p) ? { pattern: p[0], color: p[1] } : p));
57	    const nbt = legacy
58	      ? t.compound({ id: t.string("minecraft:banner"), Patterns: t.list("compound", pats.map((p) => ({ Pattern: t.string(LEGACY_PATTERN[p.pattern] ?? p.pattern), Color: t.int(DYE_INDEX.indexOf(p.color)) }))) })
59	      : t.compound({ id: t.string("minecraft:banner"), patterns: t.list("compound", pats.map((p) => ({ pattern: t.string(`minecraft:${p.pattern.replace(/^minecraft:/, "")}`), color: t.string(p.color) }))) });
60	    return [block, state, nbt];
61	  },
62	  /**
63	   * A sign with text: [block, state, nbt]. lines: up to 4 strings (front); back: up to 4 more. wood "oak", "spruce" ...
64	   * wall (facing) or standing (rotation 0..15); hanging: a hanging sign. color: dye name; glow: glowing text.
65	   * dataVersion: text is written as JSON components before 1.21.5 (4325) and as plain string components after.
66	   */
67	  sign: (wood = "oak", lines = [], { wall = true, facing = "north", rotation = 0, hanging = false, color = "black", glow = false, back = [], dataVersion = 4189 } = {}) => {
68	    const block = `${wood}_${wall ? "wall_" : ""}${hanging ? "hanging_" : ""}sign`;
69	    const state = wall ? { facing, waterlogged: "false" } : { rotation: String(rotation), waterlogged: "false", ...(hanging ? { attached: "false" } : {}) };
70	    const msg = (s) => t.string(dataVersion >= 4325 ? String(s ?? "") : JSON.stringify({ text: String(s ?? "") }));
71	    const side = (ls) => ({ messages: t.list("string", [0, 1, 2, 3].map((i) => msg(ls[i]).value)), color: t.string(color), has_glowing_text: t.byte(glow ? 1 : 0) });
72	    const nbt = t.compound({ id: t.string(hanging ? "minecraft:hanging_sign" : "minecraft:sign"), is_waxed: t.byte(0), front_text: t.compound(side(lines)), back_text: t.compound(side(back)) });
73	    return [block, state, nbt];
74	  },
75	};
76	const DYE_INDEX = ["white", "orange", "magenta", "light_blue", "yellow", "lime", "pink", "gray", "light_gray", "cyan", "purple", "blue", "brown", "green", "red", "black"];
77	const LEGACY_PATTERN = { base: "b", stripe_bottom: "bs", stripe_top: "ts", stripe_left: "ls", stripe_right: "rs", stripe_center: "cs", stripe_middle: "ms",
78	  stripe_downright: "drs", stripe_downleft: "dls", small_stripes: "ss", cross: "cr", straight_cross: "sc", diagonal_left: "ld", diagonal_right: "rud",
79	  half_vertical: "vh", half_horizontal: "hh", half_horizontal_bottom: "hhb", triangle_bottom: "bt", triangle_top: "tt", circle: "mc", rhombus: "mr",
80	  border: "bo", curly_border: "cbo", bricks: "bri", gradient: "gra", gradient_up: "gru", creeper: "cre", skull: "sku", flower: "flo", mojang: "moj", globe: "glb" };
81	
82	// ---- placement helpers ------------------------------------------------------------------------------------------
83	/** Call fn(pos, i) for count positions from `from`, `step` apart (the bay rhythm). */
84	export function tile(_g, { from = 0, step, count, to }, fn) {
85	  const n = count ?? Math.floor((to - from) / step) + 1;
86	  for (let i = 0; i < n; i++) fn(from + i * step, i);
87	}
88	
89	/** Run `paint(set)` twice: as written, and mirrored across x = cx (x' = 2cx - x), flipping east/west facings. */
90	export function mirrorX(g, cx, paint) {
91	  paint((x, y, z, block, state) => g.set(x, y, z, block, state));
92	  paint((x, y, z, block, state) => g.set(2 * cx - x, y, z, block, state && state.facing ? { ...state, facing: face.mirrorX(state.facing) } : state));
93	}
94	export function mirrorZ(g, cz, paint) {
95	  paint((x, y, z, block, state) => g.set(x, y, z, block, state));
96	  paint((x, y, z, block, state) => g.set(x, y, 2 * cz - z, block, state && state.facing ? { ...state, facing: face.mirrorZ(state.facing) } : state));
97	}
98	
99	/** Hollow box: walls (and optional floor/ceiling) of a cuboid. */
100	export function shell(g, a, b, block, { floor = true, ceiling = true, state } = {}) {
101	  const [x0, y0, z0] = a.map((v, i) => Math.min(v, b[i])), [x1, y1, z1] = a.map((v, i) => Math.max(v, b[i]));
102	  for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) {
103	    const edge = x === x0 || x === x1 || z === z0 || z === z1 || (floor && y === y0) || (ceiling && y === y1);
104	    if (edge) g.set(x, y, z, block, state);
105	  }
106	}
107	
108	/** Set a box to air (carving). Air is stored, so it clears the cell when the structure is placed. */
109	export const carve = (g, a, b) => g.fill(a, b, "minecraft:air");
110	
111	/** Replace only where the current block matches `from` (a name or a predicate). */
112	export function replace(g, a, b, from, block, state) {
113	  const match = typeof from === "function" ? from : (n) => n === ns(from);
114	  for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
115	    for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
116	      for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) if (match(g.blockAt(x, y, z))) g.set(x, y, z, block, state);
117	}
118	
119	/**
120	 * Wrap a grid so writes into protected cells are refused (counted, never thrown), so a decor script cannot
121	 * break function. protect: Set of "x,y,z" — default: the grid's own functional cells and the cells that must stay
122	 * clear around them (check.mjs functionalCells). `g.refused` lists what was blocked; report it.
123	 */
124	export function guard(g, protect) {
125	  const cells = protect ?? (() => { const f = functionalCells(g); return new Set([...f.protect.keys(), ...f.keepClear]); })();
126	  const refused = [];
127	  return new Proxy(g, {
128	    get(target, prop) {
129	      if (prop === "refused") return refused;
130	      if (prop === "protected") return cells;
131	      if (prop === "set") return (x, y, z, ...rest) => { if (cells.has(`${x},${y},${z}`)) { refused.push([x, y, z, rest[0]]); return target; } return target.set(x, y, z, ...rest); };
132	      if (prop === "fill") return (a, b, block, state) => { for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++) for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++) for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) { if (cells.has(`${x},${y},${z}`)) refused.push([x, y, z, block]); else target.set(x, y, z, block, state); } return target; };
133	      const v = Reflect.get(target, prop);
134	      return typeof v === "function" ? v.bind(target) : v;
135	    },
136	  });
137	}
138	
139	/**
140	 * Draw blocks from text, the way Litematica stores a schematic (a palette, then one index per cell): one character per
141	 * block, a legend for the characters. Far fewer tokens than a set() per block, and the layout is visible as written.
142	 *   layers(g, [x, y, z], { "#": "oak_planks", "b": ["red_bed", { facing: "south", part: "head" }], "c": "chest" }, [
143	 *     ["#####", "#b c#", "#b  #"],      // y: rows run along +x, successive rows along +z
144	 *     ["#####", "#   #", "#   #"],      // y + 1 ...
145	 *   ])
146	 * A single layer may be passed as one array of rows. Characters not in the legend (space, ".") are left as they are.
147	 * Writes go through g.set, so runParts' lock and palette report apply. Returns the number of blocks placed.
148	 */
149	export function layers(g, [x0, y0, z0], legend, rowsOrLayers) {
150	  const list = typeof rowsOrLayers[0] === "string" ? [rowsOrLayers] : rowsOrLayers;
151	  let n = 0;
152	  list.forEach((rows, dy) => rows.forEach((row, dz) => [...row].forEach((ch, dx) => {
153	    const e = legend[ch];
154	    if (e == null) return;
155	    const [block, state, nbt] = Array.isArray(e) ? e : [e];
156	    g.set(x0 + dx, y0 + dy, z0 + dz, block, state, nbt);
157	    n++;
158	  })));
159	  return n;
160	}
161	
162	/**
163	 * Run a build's parts in order so each part can only ADD to what earlier parts built: a write into a cell an earlier
164	 * part placed (air included, so no carving) is refused, counted, never thrown, so a later part can't knock holes in
165	 * a wall. Cells set before runParts (the ground) stay writable: farmland and paths may replace grass. With a palette
166	 * (palette.json, or its object: { roles: { role: [blocks] }, objects: [blocks] }), every block placed outside it is
167	 * reported. Prints one line per part, writes the reports to `report` (default parts-report.json; null for none) and
168	 * returns them.
169	 *   runParts(g, [["shell", shell.build], ["garden", garden.build]], { palette: "palette.json" })
170	 */
171	export function runParts(g, list, { palette, log = console.log, report = "parts-report.json" } = {}) {
172	  const pal = typeof palette === "string" ? (existsSync(palette) ? JSON.parse(readFileSync(palette, "utf8")) : null) : palette;
173	  const allowed = pal ? new Set([...Object.values(pal.roles ?? {}).flat(), ...(pal.objects ?? [])].map(ns)) : null;
174	  const owned = new Set(), reports = [], cellsByPart = {};
175	  for (const [name, build] of list) {
176	    const mine = new Set(), refused = [], off = new Map();
177	    const write = (target, x, y, z, block, state, nbt) => {
178	      const k = `${x},${y},${z}`;
179	      if (owned.has(k)) { refused.push([x, y, z, ns(block).replace("minecraft:", ""), target.blockAt(x, y, z).replace("minecraft:", "")]); return; }
180	      const b = ns(block);
181	      if (allowed && b !== "minecraft:air" && b !== "minecraft:cave_air" && !allowed.has(b)) off.set(b, (off.get(b) ?? 0) + 1);
182	      target.set(x, y, z, block, state, nbt);
183	      mine.add(k);
184	    };
185	    const view = new Proxy(g, {
186	      get(target, prop) {
187	        if (prop === "set") return (x, y, z, block, state, nbt) => { write(target, x, y, z, block, state, nbt); return view; };
188	        if (prop === "unset") return (x, y, z) => { write(target, x, y, z, "minecraft:air"); return view; };
189	        if (prop === "fill") return (a, b, block, state) => {
190	          for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
191	            for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
192	              for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) write(target, x, y, z, block, state);
193	          return view;
194	        };
195	        const v = Reflect.get(target, prop);
196	        return typeof v === "function" ? v.bind(target) : v;
197	      },
198	    });
199	    build(view);
200	    for (const k of mine) owned.add(k);
201	    if (process.env.MCD_PARTS_CELLS) cellsByPart[name] = [...mine].map((k) => { const c = g.get(...k.split(",").map(Number)); return [k, c ? c.block.replace("minecraft:", "") + (c.state ? JSON.stringify(c.state) : "") : "air"]; });
202	    const r = { part: name, placed: mine.size, refused: refused.length, refusedAt: refused.slice(0, 8),
203	      offPalette: [...off].map(([b, n]) => `${b.replace("minecraft:", "")} x${n}`) };
204	    reports.push(r);
205	    log(`part ${name}: ${r.placed} placed` +
206	      (r.refused ? `; REFUSED ${r.refused} writes into earlier parts (x,y,z wanted had: ${r.refusedAt.map((p) => `${p[0]},${p[1]},${p[2]} ${p[3]} ${p[4]}`).join("; ")})` : "") +
207	      (r.offPalette.length ? `; OFF-PALETTE: ${r.offPalette.join(", ")}` : ""));
208	  }
209	  if (report) writeFileSync(report, JSON.stringify(reports, null, 1));
210	  // $MCD_PARTS_CELLS=<file>: every part's cells, for measuring how much code each block cost (lab token audits)
211	  if (process.env.MCD_PARTS_CELLS) writeFileSync(process.env.MCD_PARTS_CELLS, JSON.stringify(cellsByPart));
212	  return reports;
213	}
214	
215	// ---- shape brushes (curved forms; massing) — the model picks parameters, code draws the form ---------------------
216	export * from "./shapes-curved.mjs";
217	export * from "./shapes-massing.mjs";
218	
219	// ---- landscaping brushes (terrain, strata, boulders, water, trees, paths, bridges) — see references/landscaping.md --
220	export * from "./terrain.mjs";
221	
222	// ---- roofs by style name (gable, hip, pyramid, mansard, gambrel, flat-parapet, shed, dutch-gable) — references/roofs.md
223	export * from "./roofs.mjs";
224	
225	// ---- facade brushes (signage, pilasters, surrounds, glazing, fixtures, planters) — references/detail-language.md -----
226	// Each is a function on a grid (writes only where it may: air for projections, plain wall for in-place trim; returns
227	// { cells, skipped, notes, info }) and a B.* twin that returns the plan as g.set argument lists, unchecked.
228	// at = a wall cell (bottom-left of the band / opening as seen from outside), face = the side it looks out of.
229	import { commitGrid, lookGrid, tuples } from "./brush-core.mjs";
230	import { plaquePlan, signboardPlan, buntingPlan } from "./brush-sign.mjs";
231	import { pilasterPlan } from "./brush-pilaster.mjs";
232	import { surroundPlan, glazingPlan } from "./brush-surround.mjs";
233	import { fixturePlan, planterPlan } from "./brush-fixture.mjs";
234	const withLook = (g, o) => ({ ...o, look: lookGrid(g), dataVersion: o?.dataVersion ?? g.dataVersion });
235	/** Lettering in a band: plaque(g, "LEAGUE HALL", { at, face, width, height, letter?, material?, frame?, style?, relief? }) */
236	export const plaque = (g, text, o) => commitGrid(g, plaquePlan(text, withLook(g, o)), o);
237	/** A shop sign: signboard(g, "BAKERY", { at, face, mode: "wall"|"hanging", width?, height?, wood? }) */
238	export const signboard = (g, text, o) => commitGrid(g, signboardPlan(text, withLook(g, o)), o);
239	/** Banners along a row: bunting(g, { from, to, face, colors?, every?, pattern? }) */
240	export const bunting = (g, o) => commitGrid(g, buntingPlan(withLook(g, o)), o);
241	/** A profiled pilaster: pilaster(g, { at, face, height, width?, out?, material?, profile?, shoulder? }) */
242	export const pilaster = (g, o) => commitGrid(g, pilasterPlan(o), o);
243	/** An opening surround: surround(g, { at, face, width, height, preset?, trim?, keystone?, reveal?, door?, arch? }) */
244	export const surround = (g, o) => commitGrid(g, surroundPlan(withLook(g, o)), o);
245	/** Glazing: glazing(g, { at, face, width, height, preset: grid|shopfront|transom|sidelights, frame?, door? }) */
246	export const glazing = (g, o) => commitGrid(g, glazingPlan(withLook(g, o)), o);
247	/** A light fitting: fixture(g, { at, face, mount: bracket|arm|top|hang, lamp? }) */
248	export const fixture = (g, o) => commitGrid(g, fixturePlan(withLook(g, o)), o);
249	/** A planter: planter(g, { at, face, width, kind: box|ground, depth?, plants? }) */
250	export const planter = (g, o) => commitGrid(g, planterPlan(withLook(g, o)), o);
251	Object.assign(B, {
252	  plaque: (text, o) => tuples(plaquePlan(text, o)), signboard: (text, o) => tuples(signboardPlan(text, o)), bunting: (o) => tuples(buntingPlan(o)),
253	  pilaster: (o) => tuples(pilasterPlan(o)), surround: (o) => tuples(surroundPlan(o)), glazing: (o) => tuples(glazingPlan(o)),
254	  fixture: (o) => tuples(fixturePlan(o)), planter: (o) => tuples(planterPlan(o)),
255	});
256	/** Run detail-language rules from code (weather / vary presets, treatments on every opening): returns { grid, report }. */
257	export { applyDetail as paint } from "./detail-lang.mjs";
