// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// Vanilla structure .nbt (structure blocks, Create schematics) <-> Grid, an editable block grid.
//
//   import { load, Grid } from "minecraft-design/tools/src/structure.mjs"
//   const g = await load("in.nbt")
//   g.set(3, 1, 4, "spruce_stairs", { facing: "east", half: "bottom" })
//   g.fill([0,0,0], [6,0,20], "polished_andesite")
//   g.save("out.nbt")
//
// Coordinates are structure-local: 0 <= x < size[0] (x east, y up, z south). Unset cells are not stored and are
// left untouched when the structure is placed; "minecraft:air" is stored and clears the cell. Block-entity data
// (sign text, container contents) and entities are kept as typed NBT and written back unchanged.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { parse, write, simplify, t } from "./nbt.mjs";
import { saveLitematic, isLitematic, fromLitematic } from "./litematic.mjs";

/** Minecraft data versions we know (structure files carry one). Unknown ones still load. */
export const DATA_VERSIONS = { "1.20.1": 3465, "1.20.4": 3700, "1.21.1": 3955, "1.21.4": 4189, "1.21.5": 4325,
  "1.21.8": 4440, "1.21.10": 4556, "1.21.11": 4671, "26.3": 5023 };
export const versionOfDataVersion = (dv) => Object.entries(DATA_VERSIONS).find(([, v]) => v === dv)?.[0];

const AIRS = new Set(["minecraft:air", "minecraft:cave_air", "minecraft:void_air", "minecraft:structure_void"]);
export const ns = (name) => (name.includes(":") ? name : `minecraft:${name}`);
const key = (x, y, z) => `${x},${y},${z}`;

export class Grid {
  /** @param {[number,number,number]} size */
  constructor(size, { dataVersion = DATA_VERSIONS["1.21.4"], entities = null } = {}) {
    this.size = [...size];
    this.dataVersion = dataVersion;
    this.entities = entities;                     // typed NBT list, passed through untouched
    /** @type {Map<string, {pos:number[], block:string, state?:Record<string,string>, nbt?:object}>} */
    this.cells = new Map();
  }

  inBounds(x, y, z) {
    return x >= 0 && y >= 0 && z >= 0 && x < this.size[0] && y < this.size[1] && z < this.size[2];
  }

  /** Set one block (state values become strings, as in NBT). Grows nothing: out of bounds throws. */
  set(x, y, z, block, state, nbt) {
    if (!this.inBounds(x, y, z)) throw new Error(`set out of bounds: ${x},${y},${z} (size ${this.size})`);
    const s = state && Object.keys(state).length
      ? Object.fromEntries(Object.entries(state).map(([k, v]) => [k, String(v)])) : undefined;
    this.cells.set(key(x, y, z), { pos: [x, y, z], block: ns(block), ...(s ? { state: s } : {}), ...(nbt ? { nbt } : {}) });
    return this;
  }

  get(x, y, z) { return this.cells.get(key(x, y, z)); }
  blockAt(x, y, z) { return this.get(x, y, z)?.block ?? "minecraft:air"; }
  isAir(x, y, z) { return AIRS.has(this.blockAt(x, y, z)); }
  unset(x, y, z) { this.cells.delete(key(x, y, z)); return this; }

  /** Fill the inclusive box a..b. */
  fill(a, b, block, state) {
    for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
      for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
        for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) this.set(x, y, z, block, state);
    return this;
  }

  *[Symbol.iterator]() { yield* this.cells.values(); }

  /** Non-air cells. */
  solids() { return [...this.cells.values()].filter((c) => !AIRS.has(c.block)); }
